// Top-participants praise tab: backed by window.TOP_PARTICIPANTS[win] (data/top_participants/<win>.json)
// Generated by: python top_participants.py  then  python build_dashboard.py
// PURE PRAISE VIEW: wallets that paid the most and wallets that hold the most, tied
// to the top 100 collections on Robinhood. No bot labels, no accusations.

function topp(){
  const P = window.TOP_PARTICIPANTS && window.TOP_PARTICIPANTS[win];
  if(!P){
    $('#view').innerHTML = '<div class="card">Top participants: window <b>'+esc(win)+'</b> - data not loaded. <div class="note">Rebuild: <code class="mono">python build_dashboard.py</code></div></div>';
    return;
  }
  const top = P.top100 || [];
  const ch  = P.channels  || [];
  const more= P.more      || [];
  const agg = {};
  for(const c of top){
    for(const p of (c.top_payers||[])){
      const w=p.wallet || 'unknown';
      if(!agg[w]) agg[w]={wallet:w, nfts:0, collections:0};
      agg[w].nfts += (p.nfts||0);
      agg[w].collections += 1;
    }
  }
  const topAgg = Object.values(agg).sort((a,b)=>b.nfts-a.nfts).slice(0,20);

  const gridTop = top.slice(0,40).map(c=>{
    const p0 = (c.top_payers||[])[0]||{};
    const nft = p0?fmt(p0.nfts):'—';
    return `<tr><td>${c.rank}</td><td><b>${esc(c.name)}</b><br><span class="mono">${esc(c.contract)}</span></td><td>${fmt(c.minted)}</td><td>${fmt(c.recipients)}</td><td>${fmt(c.operators)}</td><td>${pct(c.flagged_share)}</td><td class="mono">${fmt(nft)}</td></tr>`;
  }).join('');

  const topPayers = topAgg.map((b,i)=>`<tr><td>${i+1}</td><td>${addrLink(b.wallet)}</td><td>${fmt(b.nfts)}</td><td>${fmt(b.collections)}</td></tr>`).join('');

  const bestCh = ch.slice(0,8).map((c,i)=>`<tr><td><b>${esc(c.bucket)}</b></td><td>${fmt(c.collections)}</td><td>${fmt(c.mints)}</td><td>${fmt(c.wallets)}</td></tr>`).join('');

  const moreGrid = more.slice(0,30).map(c=>`<div class="card" style="flex:1 1 150px"><b>#${c.rank}</b> ${esc(c.name)} <span class="sub">${fmt(c.minted)} NFT · ${fmt(c.recipients)} wallets</span></div>`).join('');

  const html = `
  <div class="note" style="margin-top:-10px">This is <b>praise, not a flag</b>. The wallets that paid the most and the wallets that hold the most, of the <b>top 100 collections on Robinhood</b>. The people who actually showed up. Nothing here is a bot label and nothing here is an accusation.</div>
  <div class="card"><b>Top 100 collections on Robinhood &amp; the people who paid them</b>
    <div class="row" style="flex-wrap:wrap;gap:8px;margin-bottom:8px">
      <div class="kpi"><div class="v">${fmt(top.length)}</div><div class="l">top collections</div></div>
      <div class="kpi r"><div class="v">${fmt(top.reduce((s,c)=>s+(c.minted||0),0))}</div><div class="l">NFTs across them</div></div>
      <div class="kpi"><div class="v">${fmt(top.reduce((s,c)=>s+(c.recipients||0),0))}</div><div class="l">wallets that took</div></div>
      <div class="kpi a"><div class="v">${top.length?((top.reduce((s,c)=>s+c.flagged_share,0))/top.length).toFixed(1):'—'}%</div><div class="l">avg to flagged</div></div>
    </div>
    <table style="margin-top:8px"><thead><tr><th>#</th><th>collection</th><th>minted</th><th>wallets</th><th>ops</th><th>≤flag</th><th>top paid</th></tr></thead><tbody>
    ${gridTop}
    </tbody></table>
    <div class="note">${top.length} collections shown; scroll for more. "top paid" = NFTs of the collection's top paying wallet.</div>
  </div>
  <div class="card"><b>Biggest payers across the top collections</b><table><thead><tr><th>#</th><th>wallet</th><th>NFTs</th><th>collections</th></tr></thead><tbody>${topPayers}</tbody></table></div>
  <div class="card"><b>Top chains of the best projects</b>${ch.length?`<table><thead><tr><th>chain / bucket</th><th>collections</th><th>NFTs</th><th>wallets</th></tr></thead><tbody>${bestCh}</tbody></table>`:`<div class="note">no top-chains data yet</div>`}</div>
  <div class="card"><b>More collections (memes / wrapped / wild cards)</b>${more.length?`<div class="grid">${more.slice(0,30).map(c=>`<div style="border:1px solid var(--line);border-radius:8px;padding:8px"><b>#${c.rank}</b> ${esc(c.name)} <span class="sub">${fmt(c.minted)} NFT · ${fmt(c.recipients)} wallets</span></div>`).join('')}</div>`:`<div class="note">no more data yet</div>`}</div>`;

  $('#view').innerHTML = html;
}
